import{_ as a,c as r,o as t,ag as o}from"./chunks/framework.CQuhCYrb.js";const f=JSON.parse('{"title":"Research Tools","description":"","frontmatter":{"title":"Research Tools","tags":["research","osint","tools"]},"headers":[],"relativePath":"research/research-tools.md","filePath":"research/research-tools.md","lastUpdated":null}'),l={name:"research/research-tools.md"};function s(i,e,n,h,c,p){return t(),r("div",null,[...e[0]||(e[0]=[o('<h1 id="research-tools" tabindex="-1">Research Tools <a class="header-anchor" href="#research-tools" aria-label="Permalink to &quot;Research Tools&quot;">​</a></h1><h2 id="research-tools-1" tabindex="-1">Research Tools <a class="header-anchor" href="#research-tools-1" aria-label="Permalink to &quot;Research Tools&quot;">​</a></h2><h3 id="research-repositories-and-toolkits" tabindex="-1">Research Repositories and Toolkits <a class="header-anchor" href="#research-repositories-and-toolkits" aria-label="Permalink to &quot;Research Repositories and Toolkits&quot;">​</a></h3><ul><li><p><a href="https://bellingcat.gitbook.io/toolkit/most-used" target="_blank" rel="noreferrer">Bellingcat toolkit</a> - Bellingcat toolkit that stays updated.</p></li><li><p><a href="https://intelx.io/tools?tab=person" target="_blank" rel="noreferrer">Intelx Search Tools</a> – Useful for finding personal data, historical records, and more.</p></li><li><p><a href="https://inteltechniques.com/tools/Name.html" target="_blank" rel="noreferrer">Inteltechniques Search Tools</a> – Specializes in people searches and social media data.</p></li><li><p><a href="https://intelx.io/dorks" target="_blank" rel="noreferrer">Intelx Google Dork Knowledge Management</a> – Resource for understanding and using Google Dorks in OSINT research.</p></li><li><p><a href="https://start.me/p/b5Aow7/asint_collection" target="_blank" rel="noreferrer">STARTME OSINT Collection</a> – Comprehensive OSINT tool collection for researchers.</p></li><li><p><a href="https://github.com/cipher387/osint_stuff_tool_collection" target="_blank" rel="noreferrer">OSINT Tool Collection</a> – Various tools for different OSINT purposes.</p></li><li><p><a href="https://flashpoint.io/blog/osint-tools-library/" target="_blank" rel="noreferrer">Flashpoint Tools Library</a> – Curated OSINT tools and techniques</p></li></ul><h3 id="community-projects" tabindex="-1">Community Projects <a class="header-anchor" href="#community-projects" aria-label="Permalink to &quot;Community Projects&quot;">​</a></h3><ul><li><p><a href="https://github.com/agile-enigma/google_scraper" target="_blank" rel="noreferrer">Google Scraper</a> – Scrape and organize Google search results efficiently.</p></li><li><p><a href="https://researchtools.net" target="_blank" rel="noreferrer">Research Tools</a> – A hub for various research repositories.</p></li><li><p><a href="https://github.com/irregularchat/pulse-menu" target="_blank" rel="noreferrer">Pulse Query Generator</a> – Generates queries for advanced data searches and analysis.</p></li></ul><h3 id="search-platforms" tabindex="-1">Search Platforms <a class="header-anchor" href="#search-platforms" aria-label="Permalink to &quot;Search Platforms&quot;">​</a></h3><ul><li><p><a href="https://newsdata.io/search-news" target="_blank" rel="noreferrer">NewsData.io</a> API and Dashboard to get news from any country in chronological order. The dashboard works without a login.</p></li><li><p><a href="https://github.com/deepfence/ThreatMapper" target="_blank" rel="noreferrer">ThreatMapper</a> – Runtime Threat Management and Attack Path Enumeration for Cloud Native environments.</p></li><li><p>SearXNG (<a href="https://search.irregularchat.com" target="_blank" rel="noreferrer">community instance</a> | <a href="https://searx.space" target="_blank" rel="noreferrer">public instance</a> SearXNG is a free internet metasearch engine aggregating results from up to 211 search services. Users are neither tracked nor profiled. Additionally, SearXNG can be used over Tor to maintain online anonymity.</p></li></ul><h3 id="scraping" tabindex="-1">Scraping <a class="header-anchor" href="#scraping" aria-label="Permalink to &quot;Scraping&quot;">​</a></h3><p><a href="https://cobalt.tools" target="_blank" rel="noreferrer">Cobalt Tools</a> is used to download images and videos from many videos, social media, and other platforms using the web interface.</p><h3 id="satellite-and-geolocation-tools" tabindex="-1">Satellite and Geolocation Tools <a class="header-anchor" href="#satellite-and-geolocation-tools" aria-label="Permalink to &quot;Satellite and Geolocation Tools&quot;">​</a></h3><ul><li><p><a href="https://www.digisat.org/satellite-footprint-maps" target="_blank" rel="noreferrer">Digisat Satellite Coverage Maps</a> – Provides coverage maps for commercial satellite providers.</p></li><li><p><a href="https://geospy.web.app/" target="_blank" rel="noreferrer">GEO SPY</a> – AI tool used to estimate the location of where a picture was taken.</p></li><li><p><a href="https://qgis.org/en/site/" target="_blank" rel="noreferrer">ARCGIS</a> – Free version of ARCGIS, useful for making charts, maps, and geographical analysis.</p></li></ul><h3 id="services-worth-paying" tabindex="-1">Services Worth Paying <a class="header-anchor" href="#services-worth-paying" aria-label="Permalink to &quot;Services Worth Paying&quot;">​</a></h3><h3 id="face-search" tabindex="-1">Face Search <a class="header-anchor" href="#face-search" aria-label="Permalink to &quot;Face Search&quot;">​</a></h3><ul><li><a href="https://pimeyes.com/en" target="_blank" rel="noreferrer">PimEyes</a> – Advanced facial recognition search engine for finding images and data inaccessible through regular searches.</li></ul><p>[Recognition]</p>',16)])])}const g=a(l,[["render",s]]);export{f as __pageData,g as default};
